// ---------- 人物（粒子画） ----------
const STOPS = [30, 70, 110, 150, 190, 290, 335, 385];
const panels = [];

DATA.forEach((item, fi) => {
  const n = item.n;
  const raw = atob(item.data);
  const bytes = new Uint8Array(raw.length);
  for (let i = 0; i < raw.length; i++) bytes[i] = raw.charCodeAt(i);
  const dv = new DataView(bytes.buffer);

  const aspect = item.w / item.h;
  const ph = 1.7, pw = ph * aspect;

  const pos = new Float32Array(n * 3);
  const col = new Float32Array(n * 3);
  for (let i = 0; i < n; i++) {
    const o = i * 8;
    const u = dv.getUint16(o, true) / 65535;
    const v = dv.getUint16(o + 2, true) / 65535;
    const dep = dv.getUint8(o + 4) / 255;
    const r = dv.getUint8(o + 5) / 255, g = dv.getUint8(o + 6) / 255, b = dv.getUint8(o + 7) / 255;
    pos[i * 3] = (u - .5) * pw;
    pos[i * 3 + 1] = (.5 - v) * ph;
    pos[i * 3 + 2] = (dep - .5) * .22;
    const l = .299 * r + .587 * g + .114 * b;
    col[i * 3] = Math.min(1, Math.max(0, l + (r - l) * 1.5 + .02));
    col[i * 3 + 1] = Math.min(1, Math.max(0, l + (g - l) * 1.5 + .02));
    col[i * 3 + 2] = Math.min(1, Math.max(0, l + (b - l) * 1.5 + .02));
  }

  const geo = new THREE.BufferGeometry();
  geo.setAttribute('position', new THREE.BufferAttribute(pos, 3));
  geo.setAttribute('color', new THREE.BufferAttribute(col, 3));

  const g = new THREE.Group();
  const side = fi % 2 === 0 ? -1 : 1;
  g.position.set(side * (W / 2 - .12), 1.9, -STOPS[fi]);
  g.rotation.y = side > 0 ? Math.PI / 2 : -Math.PI / 2;

  const mk = (size, op, blend) => new THREE.Points(geo, new THREE.PointsMaterial({
    size: size, map: TEX_P, vertexColors: true, transparent: true, opacity: op,
    blending: blend, depthWrite: false, sizeAttenuation: true, fog: true
  }));
  g.add(mk(.055, 1, THREE.NormalBlending));
  g.add(mk(.16, .2, THREE.AdditiveBlending));
  g.add(mk(.5, .06, THREE.AdditiveBlending));
  g.visible = false;
  scene.add(g);
  panels.push({ g, name: item.name, z: -STOPS[fi] });
});

