// ---------- 行走 ----------
let idx = 0, tween = null;
const captions=new JourneyCaptions(enabled=>worldMessage('subtitle-setting',{enabled}));
// Shared layout controls reserve space for the host navigation when embedded.
// Initialize all crossing controls before assigning handlers or starting the render loop.
const journeyVeil=new WaterJourneyVeil();
const journeyWelcome=new WaterJourneyWelcome();
const journeySkip=document.createElement('button');
journeySkip.type='button';journeySkip.className='journey-skip';
journeySkip.textContent='跳过 ›';journeySkip.hidden=true;document.body.append(journeySkip);
let worldFrame=null,worldReady=false,worldShown=false,journey=null;
function worldMessage(type,extra={}){if(worldFrame)worldFrame.contentWindow.postMessage({channel:'corridor-water-v1',type,...extra},'*');}
function preloadWorld(){
 if(worldFrame)return;
 worldFrame=document.createElement('iframe');worldFrame.title='新世界 · 蓝色水境';
 worldFrame.src='新世界.html?entry=water&embedded=1';
 worldFrame.style.cssText='position:fixed;inset:0;width:100%;height:100%;border:0;z-index:40;opacity:0;pointer-events:none;background:#020b16;transition:opacity .28s ease-out;';
 worldFrame.setAttribute('aria-hidden','true');worldFrame.inert=true;document.body.append(worldFrame);
}
function startJourney(){
 preloadWorld();captions.transition();journeyWelcome.clear();journey={elapsed:0,started:performance.now(),from:camera.position.z,viewYaw:ry,viewPitch:rx,sent:false,skip:false,welcomed:false};
 journeySkip.hidden=false;document.getElementById('tip').hidden=true;document.body.classList.add('journey-active');
}
function handoffWorld(){
 if(!worldReady||journey.sent)return;
 journey.sent=true;worldMessage('subtitle-setting',{enabled:captions.enabled});worldMessage('enter',{simple:calmForest,skip:journey.skip});
}
function updateJourney(dt){
 if(!journey||worldShown)return;
 if(document.hidden)return;
 journey.elapsed+=Math.min(dt,.1);
 const t=journey.elapsed,m=WaterJourneyMotion.sample(Math.min(t,WaterJourneyMotion.handoff),calmForest);
 if(t>=1.4&&!journey.welcomed&&!journey.skip){journey.welcomed=true;journeyWelcome.show();}
 camera.position.set(0,.14+m.y,journey.from+m.z);
 const viewBlend=1-THREE.MathUtils.smoothstep(t,0,1.2);
 camera.rotation.set(m.pitch+journey.viewPitch*viewBlend,journey.viewYaw*viewBlend,m.roll);
 journeyVeil.set(m.veil);
 // Keep the architecture and water legible instead of closing the view with fog.
 scene.fog.near=Math.max(scene.fog.near,8);scene.fog.far=Math.max(scene.fog.far,75);
 camera.updateMatrixWorld();
 if(t>=WaterJourneyMotion.handoff||journey.skip)handoffWorld();
 if(t>12&&!worldReady){journeySkip.textContent='返回长廊';}
}
function restoreCorridor(){
 journeyWelcome.clear();
 
 worldMessage('suspend');worldShown=false;journey=null;
 worldFrame.style.transition='none';worldFrame.style.opacity='0';worldFrame.style.pointerEvents='none';worldFrame.inert=true;worldFrame.setAttribute('aria-hidden','true');
 journeyVeil.set(0);journeySkip.hidden=true;journeySkip.textContent='跳过 ›';document.body.classList.remove('journey-active');
 walkTo(0);camera.position.set(0,1.55,stopZ(0));camera.rotation.set(0,0,0);mx=my=ry=rx=0;tween=null;captions.setActive(true);captions.enter(1);
 renderer.domElement.focus({preventScroll:true});
}
journeySkip.onclick=()=>{
 if(journeySkip.textContent==='返回长廊'){restoreCorridor();return;}
 if(journey){journeyWelcome.clear();journey.skip=true;journey.elapsed=WaterJourneyMotion.handoff;handoffWorld();}
};
addEventListener('message',e=>{
 if(!worldFrame||e.source!==worldFrame.contentWindow||e.data?.channel!=='corridor-water-v1')return;
 if(e.data.type==='ready'){worldReady=true;worldMessage('subtitle-setting',{enabled:captions.enabled});}
 if(e.data.type==='subtitle-setting'&&typeof e.data.enabled==='boolean'){captions.setEnabled(e.data.enabled);worldMessage('subtitle-setting',{enabled:captions.enabled});}
 if(e.data.type==='enter-ready'&&journey){
  worldShown=true;captions.setActive(false);journeySkip.hidden=true;worldFrame.inert=false;worldFrame.setAttribute('aria-hidden','false');
  worldFrame.style.transition='opacity .28s ease-out';worldFrame.style.opacity='1';worldFrame.style.pointerEvents='auto';worldFrame.contentWindow.focus();journeyVeil.set(0);
 }
 if(e.data.type==='exit')restoreCorridor();
});
const stopZ = i => -STOPS[i] + 13;
function walkTo(i) {
  captions.transition();
  idx=Math.max(0,Math.min(STOPS.length-1,i));
  tween={t:0,from:camera.position.z,to:stopZ(idx)};
  document.body.dataset.stop=String(idx+1);
  const tip=document.getElementById('tip');tip.hidden=idx!==5;
  tip.textContent='轻点，潜入新世界';
  if(idx>=4)preloadWorld();
  nameEl.textContent=panels[idx]?panels[idx].name:'';
  hud.textContent=String(idx+1).padStart(2,'0')+' / '+String(STOPS.length).padStart(2,'0');
}
renderer.domElement.addEventListener('pointerdown',()=>{
  if(viewTouch||tween||journey||worldShown)return;
  if(idx>=5)startJourney();else walkTo(idx+1);
});
let mx = 0, my = 0, ry = 0, rx = 0;
const viewTouch=matchMedia("(pointer:coarse)").matches;let viewDrag=null;
renderer.domElement.addEventListener("pointerdown",e=>{if(!viewTouch||journey||worldShown)return;viewDrag={x:e.clientX,y:e.clientY,mx,my,moved:false};renderer.domElement.setPointerCapture(e.pointerId);});
renderer.domElement.addEventListener("pointermove",e=>{if(!viewDrag)return;const dx=e.clientX-viewDrag.x,dy=e.clientY-viewDrag.y;viewDrag.moved ||= Math.hypot(dx,dy)>9;mx=Math.max(-1,Math.min(1,viewDrag.mx+dx/innerWidth*2));my=Math.max(-1,Math.min(1,viewDrag.my+dy/innerHeight*2));});
renderer.domElement.addEventListener("pointercancel",()=>{viewDrag=null;});
