// Preserve existing wind hooks; cut back land/vegetation only outside the third corridor.
function blueWorldHook(mat,mode){
  const old=mat.onBeforeCompile,oldKey=mat.customProgramCacheKey();
  mat.onBeforeCompile=shader=>{
    old.call(mat,shader);shader.uniforms.blueTime=blueClock;
    shader.vertexShader='varying vec3 blueWorld;varying vec3 blueAnchor;\n'+shader.vertexShader;
    shader.vertexShader=shader.vertexShader.replace('#include <project_vertex>',`
      #include <project_vertex>
      vec4 blueVertex=vec4(transformed,1.);
      #ifdef USE_INSTANCING
      blueVertex=instanceMatrix*blueVertex;
      #endif
      blueWorld=(modelMatrix*blueVertex).xyz;
      vec4 blueOrigin=vec4(0.,0.,0.,1.);
      #ifdef USE_INSTANCING
      blueOrigin=instanceMatrix*blueOrigin;
      #endif
      blueAnchor=(modelMatrix*blueOrigin).xyz;
    `);
    shader.fragmentShader='varying vec3 blueWorld;varying vec3 blueAnchor;uniform float blueTime;\n'+blueGLSL+'\n'+shader.fragmentShader;
    if(mode==='shore'||mode==='land')shader.fragmentShader=shader.fragmentShader.replace('#include <clipping_planes_fragment>',`
      #include <clipping_planes_fragment>
      vec3 shorePoint=${mode==='land'?'blueWorld':'blueAnchor'};
      float shore=blueZone(shorePoint.z);
      ${mode==='land'?'if(abs(shorePoint.x)>4.09 && shore>.34) discard;':'if(abs(shorePoint.x)>4.09 && shore>blueHash(floor(shorePoint.xz*.7))*.5+.08) discard;'}
    `);
    if(mode==='light')shader.fragmentShader=shader.fragmentShader.replace('#include <emissivemap_fragment>',`
      #include <emissivemap_fragment>
      float low=exp(-max(0.,blueWorld.y)*1.65)*(1.-smoothstep(1.6,3.6,blueWorld.y));
      float caustic=blueWake(blueWorld.xz*1.6+vec2(blueWorld.y*.6),blueTime);
      totalEmissiveRadiance+=vec3(.030,.145,.190)*caustic*blueZone(blueWorld.z)*low*(.25+.75*smoothstep(-7.,-3.2,abs(blueWorld.x)));
    `);
  };
  mat.customProgramCacheKey=()=>oldKey+'-third-blue-'+mode;mat.needsUpdate=true;
}
