function makeFloodMat(edgeMode){
  return new THREE.ShaderMaterial({
    uniforms:{uTime:blueClock,uZone:{value:0},uEdge:{value:edgeMode}},
    transparent:true,depthWrite:false,
    blending:edgeMode?THREE.AdditiveBlending:THREE.NormalBlending,
    vertexShader:`varying vec3 wp;
      void main(){vec4 w=modelMatrix*vec4(position,1.);wp=w.xyz;gl_Position=projectionMatrix*viewMatrix*w;}`,
    fragmentShader:`
      varying vec3 wp;
      uniform float uTime;uniform float uZone;uniform float uEdge;
      float hash(vec2 p){p=fract(p*vec2(123.34,456.21));p+=dot(p,p+45.32);return fract(p.x*p.y);}
      float noise(vec2 p){vec2 i=floor(p),f=fract(p);f=f*f*(3.-2.*f);
        return mix(mix(hash(i),hash(i+vec2(1.,0.)),f.x),mix(hash(i+vec2(0.,1.)),hash(i+vec2(1.,1.)),f.x),f.y);}
      float fbm(vec2 p){float v=0.,a=.5;for(int i=0;i<4;i++){v+=a*noise(p);p=p*2.03+vec2(1.7,9.2);a*=.5;}return v;}
      void main(){
        if(uZone<.01) discard;
        vec2 p=wp.xz;float T=uTime;
        float side=wp.x>0.?1.:-1.;

        // 与外侧水面完全相同的三组浪，取岸线处波高
        float sx=3.06;
        float w1=sin(sx*.34+p.y*.21-T*.55);
        float w2=sin(sx*.71-p.y*.53+T*.78);
        float w3=sin(sx*1.6+p.y*1.1-T*1.2);
        float h=w1*.060+w2*.028+w3*.014;

        // 慢包络：让大潮偶尔才来
        float env=smoothstep(.26,.72,fbm(vec2(p.y*.07+side*9.,T*.045)));
        float spill=smoothstep(.012,.070,h)*env;

        float reach=spill*2.55;
        float x=abs(wp.x);
        float edgeX=3.0-reach+(fbm(vec2(p.y*.6,T*.15))-.5)*.28;
        float wet=smoothstep(edgeX-.05,edgeX+.18,x);

        // 前沿：与水面同一套青色
        float e=exp(-pow((x-edgeX)/.055,2.))*clamp(spill*1.4,0.,1.);

        // 退水湿痕
        float h2=sin(sx*.34+p.y*.21-(T-1.8)*.55)*.060
                +sin(sx*.71-p.y*.53+(T-1.8)*.78)*.028
                +sin(sx*1.6+p.y*1.1-(T-1.8)*1.2)*.014;
        float env2=smoothstep(.26,.72,fbm(vec2(p.y*.07+side*9.,(T-1.8)*.045)));
        float spill2=smoothstep(.012,.070,h2)*env2;
        float stain=clamp(spill2-spill,0.,1.)*.6;

        if(uEdge>.5){
          gl_FragColor=vec4(vec3(.38,.88,1.0)*1.6,e*.62*uZone);
        }else{
          float sh=sin(p.y*3.4+T*1.1)*.5+.5;
          float a=(wet*.52+stain*.16)*uZone;
          gl_FragColor=vec4(vec3(.020,.070,.100)*(.82+sh*.34),a);
        }
      }`
  });
}
